package com.morongaming.forsakenrealm;
import android.content.Context;import android.graphics.*;import android.view.*;import android.widget.Toast;
/** Approved isometric layout editor. The same draft supplies the drawing, hit regions and saved game controls. */
final class ControlEditor extends View {
 interface Host{void save(CombatControls layout);void close();void preview(Canvas canvas,float width,float height);}
 final Host host;final CombatControls draft;final MenuFrame f=new MenuFrame();int selection;float worldW=960,worldH=540,previewScale=1,previewLeft,previewTop,offsetX,offsetY,downX,downY;boolean dragging,pressed;
 ControlEditor(Context c,CombatControls current,Host h){super(c);host=h;draft=current.copy();setContentDescription("Control layout. Drag buttons and movement pad, adjust each size and opacity. Apply saves; Cancel keeps the previous layout.");}
 protected void onDraw(Canvas c){f.begin(c,this);worldW=getWidth();worldH=getHeight();f.text(c,"FORSAKEN REALM / CONTROL LAYOUT",24,39,25,910);f.text(c,"Drag a button in your isometric scene, then adjust its size.",24,68,16,900);f.panel(c,24,94,672,384,false);previewScale=Math.min(660/worldW,372/worldH);previewLeft=30+(660-worldW*previewScale)/2;previewTop=100+(372-worldH*previewScale)/2;c.save();c.clipRect(30,100,690,472);c.translate(previewLeft,previewTop);c.scale(previewScale,previewScale);host.preview(c,worldW,worldH);float unit=Math.min(worldW/960,worldH/540);for(int i=0;i<CombatControls.LABELS.length;i++){if(!CombatControls.enabled(i))continue;float x=draft.x(i,worldW,worldH),y=draft.y(i,worldW,worldH),r=draft.radius(i,worldW,worldH);boolean art=ApprovedCombatButtons.draw(c,getContext(),i,x,y,r,draft.opacities[i]);if(!art){f.paint.setColor(0xe51a201b);c.drawCircle(x,y,r,f.paint);}if(i==selection){f.paint.setStyle(Paint.Style.STROKE);f.paint.setStrokeWidth(2*unit);f.paint.setColor(0xffffda86);c.drawCircle(x,y,r,f.paint);f.paint.setStyle(Paint.Style.FILL);}if(i==CombatControls.INTERACT||i==CombatControls.SPRINT||i==CombatControls.BLOCK||i==CombatControls.MAP){f.paint.setTypeface(Typeface.create(Typeface.SANS_SERIF,Typeface.BOLD));f.paint.setTextSize(11*unit);f.paint.setColor(Color.WHITE);String label=CombatControls.LABELS[i];c.drawText(label,x-f.paint.measureText(label)/2,y+4*unit,f.paint);}}c.restore();
 f.panel(c,714,94,222,384,false);f.text(c,"PRESET LAYOUTS",730,121,18,190);String[] names={"DEFAULT (MOBA)","LEFT HANDED","COMPACT","LARGE BUTTONS"};for(int i=0;i<4;i++){f.panel(c,730,138+i*43,190,34,false);f.text(c,names[i],744,161+i*43,14,162);}f.text(c,"BUTTON SIZE",730,338,17,190);f.panel(c,730,352,45,40,false);f.text(c,"−",746,379,23,28);f.text(c,Math.round(draft.sizes[selection]*100)+"%",794,379,20,80);f.panel(c,875,352,45,40,false);f.text(c,"+",889,379,23,28);f.text(c,"OPACITY",730,414,17,190);f.panel(c,730,423,45,40,false);f.text(c,"−",746,450,23,28);f.text(c,Math.round(draft.opacities[selection]*100)+"%",794,450,20,80);f.panel(c,875,423,45,40,false);f.text(c,"+",889,450,23,28);
 f.panel(c,24,490,140,36,false);f.text(c,"< CANCEL",39,514,16,112);f.panel(c,176,490,140,36,false);f.text(c,"RESET",219,514,16,88);f.text(c,CombatControls.LABELS[selection]+"  /  "+Math.round(draft.sizes[selection]*100)+"%",333,514,15,360);f.panel(c,714,490,222,36,true);f.text(c,"APPLY CHANGES",745,514,17,185);c.restore();}
 public boolean performClick(){super.performClick();return true;}
 private void resize(float delta){draft.sizes[selection]=Math.max(.6f,Math.min(1.8f,draft.sizes[selection]+delta));invalidate();}
 private void opacity(float delta){draft.opacities[selection]=Math.max(.35f,Math.min(1,draft.opacities[selection]+delta));invalidate();}
 public boolean onTouchEvent(MotionEvent e){float x=f.x(e.getX()),y=f.y(e.getY()),wx=(x-previewLeft)/previewScale,wy=(y-previewTop)/previewScale;int type=e.getActionMasked();if(type==MotionEvent.ACTION_DOWN){pressed=true;downX=x;downY=y;int hit=x>=30&&x<=690&&y>=100&&y<=472?draft.hit(wx,wy,worldW,worldH,true):-1;dragging=hit>=0;if(dragging){selection=hit;offsetX=wx-draft.x(hit,worldW,worldH);offsetY=wy-draft.y(hit,worldW,worldH);invalidate();}return true;}if(type==MotionEvent.ACTION_CANCEL||type==MotionEvent.ACTION_POINTER_DOWN){pressed=dragging=false;return true;}if(type==MotionEvent.ACTION_MOVE&&dragging){draft.move(selection,wx-offsetX,wy-offsetY,worldW,worldH);invalidate();return true;}if(type!=MotionEvent.ACTION_UP||!pressed)return true;pressed=false;if(dragging){dragging=false;return true;}if(Math.hypot(x-downX,y-downY)>14)return true;performClick();if(x>=730&&x<=920&&y>=138&&y<301&&(y-138)%43<=34){draft.preset((int)((y-138)/43));invalidate();}else if(y>=352&&y<=392){if(x>=730&&x<=775)resize(-.05f);else if(x>=875&&x<=920)resize(.05f);}else if(y>=423&&y<=463){if(x>=730&&x<=775)opacity(-.05f);else if(x>=875&&x<=920)opacity(.05f);}else if(y>=490&&y<=526){if(x>=24&&x<=164)host.close();else if(x>=176&&x<=316){draft.reset();invalidate();}else if(x>=714&&x<=936){if(draft.overlaps(worldW,worldH)){Toast.makeText(getContext(),"Separate overlapping controls before applying",Toast.LENGTH_LONG).show();}else host.save(draft);}}return true;}
}
